-- LKPD tied to a public flipbook slug. Student access is derived from a
-- published LKPD, never from a browser-supplied lifecycle record.
create table public.activity_definitions (
  id uuid primary key default gen_random_uuid(), owner_admin_id uuid not null references public.admin_profiles(id) on delete restrict,
  public_slug text unique, title text not null check (char_length(btrim(title)) between 1 and 200),
  status text not null default 'draft' check (status in ('draft','published','closed')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.activity_questions (
  id uuid primary key default gen_random_uuid(), definition_id uuid not null references public.activity_definitions(id) on delete cascade,
  position integer not null check(position >= 0), question_type text not null check(question_type in ('multiple_choice','essay')),
  prompt text not null check(char_length(btrim(prompt)) between 1 and 4000), options jsonb not null default '[]'::jsonb,
  correct_answer text, max_score numeric(8,2) not null default 1 check(max_score > 0 and max_score <= 1000), rubric text,
  unique(definition_id, position), check(jsonb_typeof(options) = 'array')
);
alter table public.activity_attempts add column if not exists student_full_name text;
alter table public.activity_attempts add column if not exists student_class text;
alter table public.activity_attempts add column if not exists student_school text;
alter table public.activity_attempts add column if not exists draft_payload jsonb not null default '{}'::jsonb;
alter table public.activity_attempts add column if not exists updated_at timestamptz not null default now();
alter table public.attempt_results add column if not exists auto_score numeric(8,2) not null default 0;
alter table public.attempt_results add column if not exists manual_score numeric(8,2) not null default 0;
alter table public.attempt_results add column if not exists final_score numeric(8,2);
alter table public.attempt_results add column if not exists review_status text not null default 'needs_review' check(review_status in ('needs_review','graded'));
create table public.attempt_manual_marks (
  attempt_id uuid not null references public.activity_attempts(id) on delete cascade, question_id uuid not null references public.activity_questions(id) on delete restrict,
  score numeric(8,2) not null check(score >= 0), comment text, marked_by uuid not null references public.admin_profiles(id), marked_at timestamptz not null default now(), primary key(attempt_id, question_id)
);
alter table public.activity_definitions enable row level security; alter table public.activity_questions enable row level security; alter table public.attempt_manual_marks enable row level security;
create policy "admins manage their lkpd" on public.activity_definitions for all to authenticated using (owner_admin_id=auth.uid() and exists(select 1 from public.admin_profiles where id=auth.uid() and access_status='active')) with check (owner_admin_id=auth.uid() and exists(select 1 from public.admin_profiles where id=auth.uid() and access_status='active'));
create policy "admins manage their lkpd questions" on public.activity_questions for all to authenticated using (exists(select 1 from public.activity_definitions d where d.id=definition_id and d.owner_admin_id=auth.uid())) with check (exists(select 1 from public.activity_definitions d where d.id=definition_id and d.owner_admin_id=auth.uid()));
create policy "admins read marks for their lkpd" on public.attempt_manual_marks for select to authenticated using (exists(select 1 from public.activity_attempts a join public.activity_definitions d on d.id=a.activity_version_id where a.id=attempt_id and d.owner_admin_id=auth.uid()));
create policy "admins read attempts for their lkpd" on public.activity_attempts for select to authenticated using (exists(select 1 from public.activity_definitions d where d.id=activity_version_id and d.owner_admin_id=auth.uid()));
create policy "admins read results for their lkpd" on public.attempt_results for select to authenticated using (exists(select 1 from public.activity_definitions d where d.id=activity_version_id and d.owner_admin_id=auth.uid()));
create policy "admins read answers for their lkpd" on public.attempt_answers for select to authenticated using (exists(select 1 from public.activity_attempts a join public.activity_definitions d on d.id=a.activity_version_id where a.id=attempt_id and d.owner_admin_id=auth.uid()));

-- Active administrators author a full definition atomically. Answers remain server-side.
create or replace function public.admin_save_lkpd(p_definition_id uuid, p_title text, p_public_slug text, p_status text, p_questions jsonb) returns uuid language plpgsql security definer set search_path=public,private as $$
declare v_id uuid := coalesce(p_definition_id, gen_random_uuid()); v_item jsonb; v_pos integer:=0; v_type text; v_options jsonb; v_score numeric;
begin
 if auth.uid() is null or not exists(select 1 from public.admin_profiles where id=auth.uid() and access_status='active') then raise exception 'forbidden' using errcode='42501'; end if;
 if btrim(coalesce(p_title,''))='' or char_length(btrim(p_title))>200 or p_status not in ('draft','published','closed') or jsonb_typeof(p_questions)<>'array' or jsonb_array_length(p_questions)>50 then raise exception 'invalid_lkpd' using errcode='22023'; end if;
 if p_definition_id is not null and not exists(select 1 from public.activity_definitions where id=p_definition_id and owner_admin_id=auth.uid()) then raise exception 'not_found' using errcode='42501'; end if;
 if p_status='published' and (coalesce(p_public_slug,'') !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' or not exists(select 1 from public.published_flipbooks where slug=p_public_slug and owner_admin_id=auth.uid())) then raise exception 'invalid_publication' using errcode='22023'; end if;
 if p_status='published' and jsonb_array_length(p_questions)=0 then raise exception 'questions_required' using errcode='22023'; end if;
 insert into public.activity_definitions(id,owner_admin_id,public_slug,title,status) values(v_id,auth.uid(),nullif(p_public_slug,''),btrim(p_title),p_status) on conflict(id) do update set public_slug=excluded.public_slug,title=excluded.title,status=excluded.status,updated_at=now();
 delete from public.activity_questions where definition_id=v_id;
 for v_item in select value from jsonb_array_elements(p_questions) loop
   v_type:=v_item->>'question_type'; v_options:=coalesce(v_item->'options','[]'::jsonb); v_score:=coalesce((v_item->>'max_score')::numeric,1);
   if v_type not in ('multiple_choice','essay') or btrim(coalesce(v_item->>'prompt',''))='' or v_score<=0 or v_score>1000 or jsonb_typeof(v_options)<>'array' or jsonb_array_length(v_options)>8 then raise exception 'invalid_question' using errcode='22023'; end if;
   if v_type='multiple_choice' and (jsonb_array_length(v_options)<2 or coalesce(v_item->>'correct_answer','')='' or not exists(select 1 from jsonb_array_elements_text(v_options) x where x=btrim(v_item->>'correct_answer'))) then raise exception 'invalid_multiple_choice' using errcode='22023'; end if;
   insert into public.activity_questions(definition_id,position,question_type,prompt,options,correct_answer,max_score,rubric) values(v_id,v_pos,v_type,btrim(v_item->>'prompt'),v_options,nullif(v_item->>'correct_answer',''),v_score,nullif(v_item->>'rubric','')); v_pos:=v_pos+1;
 end loop; return v_id;
end; $$;
grant execute on function public.admin_save_lkpd(uuid,text,text,text,jsonb) to authenticated;

-- Replaces the experimental lifecycle lookup with the actual published LKPD.
create or replace function public.start_activity_session(p_activity_version_id uuid,p_token_hash text,p_expires_at timestamptz,p_deadline_at timestamptz) returns jsonb language plpgsql security definer set search_path=public,private as $$
declare v_attempt uuid:=gen_random_uuid(); v_definition public.activity_definitions; v_end timestamptz;
begin select * into v_definition from public.activity_definitions where id=p_activity_version_id and status='published' for share; if v_definition.id is null or p_token_hash !~ '^[0-9a-f]{64}$' or p_expires_at<=now() then raise exception 'activity_not_available' using errcode='28000'; end if; v_end:=least(p_expires_at,p_deadline_at); if v_end<=now() then raise exception 'invalid_session_contract' using errcode='22023'; end if; insert into public.activity_attempts(id,activity_version_id,session_token_hash,deadline_at,status) values(v_attempt,v_definition.id,p_token_hash,v_end,'active'); insert into public.activity_sessions(attempt_id,token_hash,expires_at) values(v_attempt,p_token_hash,v_end); return jsonb_build_object('attempt_id',v_attempt,'expires_at',v_end); end; $$;
create or replace function public.identify_activity_attempt(p_attempt uuid,p_token_hash text,p_full_name text,p_class text,p_school text) returns void language plpgsql security definer set search_path=public,private as $$ begin if char_length(btrim(coalesce(p_full_name,''))) not between 2 and 160 or char_length(btrim(coalesce(p_class,''))) not between 1 and 80 or char_length(btrim(coalesce(p_school,''))) not between 2 and 160 then raise exception 'invalid_student_identity' using errcode='22023'; end if; update public.activity_attempts set student_full_name=btrim(p_full_name),student_class=btrim(p_class),student_school=btrim(p_school),updated_at=now() where id=p_attempt and session_token_hash=p_token_hash and status='active'; if not found then raise exception 'unauthorized' using errcode='28000'; end if; end; $$;
create or replace function public.save_activity_draft(p_attempt uuid,p_token_hash text,p_payload jsonb) returns void language plpgsql security definer set search_path=public,private as $$ begin if jsonb_typeof(p_payload)<>'object' then raise exception 'invalid_draft' using errcode='22023'; end if; update public.activity_attempts set draft_payload=p_payload,updated_at=now() where id=p_attempt and session_token_hash=p_token_hash and status='active' and deadline_at>now(); if not found then raise exception 'attempt_not_accepting' using errcode='22023'; end if; end; $$;
create or replace function public.student_submit_activity(p_attempt_id uuid,p_session_token_hash text,p_activity_version_id uuid,p_payload jsonb,p_idempotency_key uuid,p_request_fingerprint text) returns jsonb language plpgsql security definer set search_path=public,private as $$
declare v_attempt public.activity_attempts; v_existing public.activity_submit_idempotency; v_auto numeric:=0; v_total numeric:=0; v_essay_count integer:=0;
begin select * into v_attempt from public.activity_attempts where id=p_attempt_id for update; if v_attempt.id is null or v_attempt.activity_version_id<>p_activity_version_id or v_attempt.session_token_hash<>p_session_token_hash or v_attempt.status<>'active' or v_attempt.deadline_at<=now() or jsonb_typeof(p_payload)<>'object' then raise exception 'attempt_not_accepting' using errcode='28000'; end if; select * into v_existing from public.activity_submit_idempotency where attempt_id=p_attempt_id and idempotency_key=p_idempotency_key; if found then return v_existing.outcome; end if; select coalesce(sum(max_score),0),count(*) filter(where question_type='essay') into v_total,v_essay_count from public.activity_questions where definition_id=p_activity_version_id; select coalesce(sum(q.max_score) filter(where q.question_type='multiple_choice' and p_payload->>q.id::text=q.correct_answer),0) into v_auto from public.activity_questions q where q.definition_id=p_activity_version_id; insert into public.attempt_answers(id,attempt_id,payload) values(gen_random_uuid(),p_attempt_id,p_payload); update public.activity_attempts set status='finalized',finalized_at=now(),draft_payload=p_payload,updated_at=now() where id=p_attempt_id; insert into public.attempt_results(attempt_id,activity_version_id,result_payload,auto_score,manual_score,final_score,review_status) values(p_attempt_id,p_activity_version_id,jsonb_build_object('status','accepted'),v_auto,0,case when v_essay_count=0 and v_total>0 then round(v_auto/v_total*100,2) end,case when v_essay_count=0 then 'graded' else 'needs_review' end); insert into public.activity_submit_idempotency values(p_attempt_id,p_idempotency_key,p_request_fingerprint,jsonb_build_object('status','accepted','attempt_id',p_attempt_id)); return jsonb_build_object('status','accepted','attempt_id',p_attempt_id); end; $$;
create or replace function public.admin_grade_essay(p_actor uuid,p_attempt uuid,p_question uuid,p_score numeric,p_comment text default null) returns void language plpgsql security definer set search_path=public,private as $$
declare v_max numeric; v_auto numeric; v_manual numeric; v_total numeric; v_open integer;
begin if p_actor<>auth.uid() or not exists(select 1 from public.admin_profiles where id=p_actor and access_status='active') then raise exception 'forbidden'; end if; select q.max_score into v_max from public.activity_questions q join public.activity_attempts a on a.activity_version_id=q.definition_id join public.activity_definitions d on d.id=q.definition_id where q.id=p_question and q.question_type='essay' and a.id=p_attempt and d.owner_admin_id=p_actor; if v_max is null or p_score<0 or p_score>v_max then raise exception 'invalid_score'; end if; insert into public.attempt_manual_marks values(p_attempt,p_question,p_score,p_comment,p_actor,now()) on conflict(attempt_id,question_id) do update set score=excluded.score,comment=excluded.comment,marked_by=excluded.marked_by,marked_at=now(); select auto_score into v_auto from public.attempt_results where attempt_id=p_attempt; select coalesce(sum(score),0) into v_manual from public.attempt_manual_marks where attempt_id=p_attempt; select coalesce(sum(q.max_score),0) into v_total from public.activity_questions q join public.activity_attempts a on a.activity_version_id=q.definition_id where a.id=p_attempt; select count(*) into v_open from public.activity_questions q join public.activity_attempts a on a.activity_version_id=q.definition_id left join public.attempt_manual_marks m on m.attempt_id=a.id and m.question_id=q.id where a.id=p_attempt and q.question_type='essay' and m.question_id is null; update public.attempt_results set manual_score=v_manual,final_score=case when v_total>0 then round((v_auto+v_manual)/v_total*100,2) end,review_status=case when v_open=0 then 'graded' else 'needs_review' end where attempt_id=p_attempt; end; $$;
grant execute on function public.start_activity_session(uuid,text,timestamptz,timestamptz),public.identify_activity_attempt(uuid,text,text,text,text),public.save_activity_draft(uuid,text,jsonb),public.student_submit_activity(uuid,text,uuid,jsonb,uuid,text),public.admin_grade_essay(uuid,uuid,uuid,numeric,text) to service_role;
